# spaCy Matcher patterns for Pronominal Idiomatic Meaning Shifts
pattern_pronominal_idiomatic = [
    # Pattern 1: s'en aller (e.g., "m'en vais", "s'en sont allés", "allons-nous-en")
    [
        {"POS": "PRON", "LEMMA": {"IN": ["me", "te", "se", "nous", "vous"]}},
        {"LOWER": "en"},
        {"POS": {"IN": ["VERB", "AUX"]}, "LEMMA": "aller"}
    ],
    # Pattern 2: en vouloir à (e.g., "lui en veut", "ne m'en voulez pas")
    [
        {"LOWER": "en"},
        {"POS": {"IN": ["VERB", "AUX"]}, "LEMMA": "vouloir"},
        {"POS": "ADP", "LOWER": {"IN": ["à", "au", "aux", "a"]}}
    ],
    # Pattern 3: s'en prendre à (e.g., "t'en prends à", "s'en est pris à")
    [
        {"POS": "PRON", "LEMMA": {"IN": ["me", "te", "se", "nous", "vous"]}},
        {"LOWER": "en"},
        {"POS": {"IN": ["VERB", "AUX"]}, "LEMMA": "prendre"},
        {"POS": "ADP", "LOWER": {"IN": ["à", "au", "aux", "a"]}}
    ],
    # Pattern 4: se passer de (e.g., "se passer de", "nous passer de")
    [
        {"POS": "PRON", "LEMMA": {"IN": ["me", "te", "se", "nous", "vous"]}},
        {"POS": "ADV", "OP": "*"},
        {"POS": {"IN": ["VERB", "AUX"]}, "LEMMA": "passer"},
        {"POS": "ADP", "LOWER": {"IN": ["de", "d'", "du", "des"]}}
    ],
    # Pattern 5: y tenir (e.g., "j'y tiens", "y tenait")
    [
        {"LOWER": "y"},
        {"POS": "ADV", "OP": "*"},
        {"POS": {"IN": ["VERB", "AUX"]}, "LEMMA": "tenir"}
    ],
    # Pattern 6: s'y connaître en (e.g., "s'y connaît en", "m'y connais en")
    [
        {"POS": "PRON", "LEMMA": {"IN": ["me", "te", "se", "nous", "vous"]}},
        {"LOWER": "y"},
        {"POS": {"IN": ["VERB", "AUX"]}, "LEMMA": "connaître"},
        {"POS": "ADP", "LOWER": "en"}
    ]
]

pattern = [
    # Pattern 1: Formal locutions (il convient de, il est à noter que, il appert que, quant à, en ce qui concerne)
    [
        {"LOWER": "il"},
        {"LOWER": {"IN": ["convient", "appert"]}},
        {"LOWER": "de"}
    ],
    [
        {"LOWER": "il"},
        {"LOWER": "est"},
        {"LOWER": "à"},
        {"LOWER": "noter"},
        {"LOWER": "que"}
    ],
    [
        {"LOWER": "quant"},
        {"LOWER": {"IN": ["à", "au", "aux", "a"]}}
    ],
    [
        {"LOWER": "en"},
        {"LOWER": "ce"},
        {"LOWER": "qui"},
        {"LOWER": "concerne"}
    ],
    # Pattern 2: Informal spoken contractions (y'a, y'a pas, t'as, t'es, j'sais)
    [
        {"LOWER": {"IN": ["y'a", "t'as", "t'es", "j'sais", "c'est"]}}
    ],
    # Pattern 3: Dropped 'ne' in informal negation (PRON + VERB + pas/plus/jamais without 'ne')
